    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null");
    }
    try {
        // Create left partition vertices
        V u1 = target.addVertex();
        V u2 = target.addVertex();
        // Create right partition vertices
        V v1 = target.addVertex();
        V v2 = target.addVertex();
        // Store vertices in the result map
        resultMap.put("U1", u1);
        resultMap.put("U2", u2);
        resultMap.put("V1", v1);
        resultMap.put("V2", v2);
        // Add edges to form a complete bipartite graph K_{2,2}
        target.addEdge(u1, v1);
        target.addEdge(u1, v2);
