static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    try{
        String s = Long.toString(timeBucket);
        if(s.length() != 8){
            throw new IllegalArgumentException("timeBucket must be in YYYYMMDD format");
        }
        int year = Integer.parseInt(s.substring(0,4));
        int month = Integer.parseInt(s.substring(4,6));
        int day = Integer.parseInt(s.substring(6,8));
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        java.time.LocalDate firstDay = java.time.LocalDate.of(year, 1, 1);
        long daysBetween = java.time.temporal.ChronoUnit.DAYS.between(firstDay, date);
        long bucketStartDays = (daysBetween / dayStep) * dayStep;
        java.time.LocalDate bucketStart = firstDay.plusDays(bucketStartDays);
        return bucketStart.getYear() * 10000L + bucketStart.getMonthValue() * 100L + bucketStart.getDayOfMonth();
    }catch(java.time.DateTimeException | NumberFormatException e){
        throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket, e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    final int end = index + len;
    if (index < 0 || end > str.length()) {
        throw new IndexOutOfBoundsException("index: " + index + ", len: " + len + ", str.length: " + str.length());
    }
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (low >= 0xDC00 && low <= 0xDFFF) {
                // valid surrogate pair
                size += 4;
                i++; // skip low surrogate
            } else {
                // unmatched high surrogate
                size += 3;
            }
        } else if (ch >= 0xDC00 && ch <= 0xDFFF) {
            // unmatched low surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

