public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if (str == null) {
        return lb;
    }
    try {
        byte[] utf8 = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        // Assume LinkedBuffer has a write(byte[]) method; if not, adjust accordingly.
        lb.write(utf8);
    } catch (Exception e) {
        // Fallback: write using platform default encoding if UTF-8 conversion fails
        byte[] fallback = str.toString().getBytes();
        lb.write(fallback);
    }
    return lb;
}

public void removeFromTreeEdgeList() {
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = this.nextTreeEdge;
    } else {
        // this is the head of the list
        TreeEdge.firstTreeEdge = this.nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = this.prevTreeEdge;
    } else {
        // this is the tail of the list
        TreeEdge.lastTreeEdge = this.prevTreeEdge;
    }
    this.prevTreeEdge = null;
    this.nextTreeEdge = null;
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    try {
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        java.util.regex.Matcher matcher = pattern.matcher(value);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                varValue = "";
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
        }
        matcher.appendTail(sb);
        return sb.toString();
    } catch (Exception e) {
        // If substitution fails, return the original value
        return value;
    }
}

