public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        return 2;
    }
    try {
        int limit = desiredCapacity;
        if (desiredCapacity >= 1000) {
            long l = (long) desiredCapacity * 111L / 100L; // 1.11 * desiredCapacity
            limit = (l > Integer.MAX_VALUE) ? Integer.MAX_VALUE : (int) l;
        }
        for (int i = desiredCapacity; i <= limit; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
        for (int i = limit + 1; ; i++) {
            if (isPrime(i)) {
                return i;
            }
            if (i == Integer.MAX_VALUE) {
                throw new IllegalStateException("No prime found within integer range");
            }
        }
    } catch (ArithmeticException e) {
        throw new IllegalArgumentException("desiredCapacity too large", e);
    }
}

