protected int removeUnusedNodes() {
    int removed = 0;
    try {
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            if (children != null) {
                for (Category child : children) {
                    stack.push(child);
                }
            }
            if (!current.isActive() && current != root) {
                Category parent = current.getParent();
                if (parent != null) {
                    parent.removeChild(current);
                    removed++;
                }
            }
        }
    } catch (Exception e) {
        // Exception handling: log or rethrow as needed
    }
    return removed;
}

