final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    try {
        // CONSTANT_Utf8 tag is 1
        int tag = classFileBuffer[constantPoolEntryIndex] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
        }
        int length = ((classFileBuffer[constantPoolEntryIndex + 1] & 0xFF) << 8)
                   | (classFileBuffer[constantPoolEntryIndex + 2] & 0xFF);
        if (length < 0) {
            throw new IllegalArgumentException("Negative UTF8 length at index " + constantPoolEntryIndex);
        }
        int start = constantPoolEntryIndex + 3;
        if (start + length > classFileBuffer.length) {
            throw new IllegalArgumentException("UTF8 string exceeds buffer bounds");
        }
        String str = new String(classFileBuffer, start, length, java.nio.charset.StandardCharsets.UTF_8);
        int strLen = str.length();
        if (charBuffer.length < strLen) {
            throw new IllegalArgumentException("Provided charBuffer too small for UTF8 string");
        }
        str.getChars(0, strLen, charBuffer, 0);
        return str;
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid constantPoolEntryIndex: " + constantPoolEntryIndex, e);
    }
}

