private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop must not be null");
    }
    // Accept only 1 or -1 as valid directions
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be 1 or -1");
    }

    Node current = start;
    java.util.Set<Node> visited = new java.util.HashSet<>();

    while (!current.equals(stop) && !predicate.test(current) && visited.add(current)) {
        // Move to the next node in the specified direction.
        // It is assumed that Node has a method getNext(int dir) that returns the adjacent node.
        current = current.getNext(dir);
        if (current == null) {
            // If traversal cannot continue, break out of the loop.
            break;
        }
    }

    // Return a circulator positioned at the found node (or at stop if the predicate never matched).
    return new OuterFaceCirculator(current, dir);
}

