private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // If the node is not part of this list, we cannot unlink it
    if (node.prev == null && node.next == null && node != first && node != last) {
        return false;
    }
    try {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        if (prev != null) {
            prev.next = next;
        } else {
            first = next;
        }

        if (next != null) {
            next.prev = prev;
        } else {
            last = prev;
        }

        // Detach the node completely
        node.prev = null;
        node.next = null;

        if (size > 0) {
            size--;
        }
        return true;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return false
        return false;
    }
}

