public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    try {
        boolean isAbsolute = path.startsWith("/");
        Deque<String> stack = new ArrayDeque<>();

        // Process base path
        String[] baseParts = path.split("/");
        for (String part : baseParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(part);
            }
        }

        // Process relative path
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                } else if (!isAbsolute) {
                    // For relative base, keep leading ".."
                    stack.addLast("..");
                }
            } else {
                stack.addLast(part);
            }
        }

        // Build result
        StringBuilder result = new StringBuilder();
        if (isAbsolute) {
            result.append("/");
        }
        Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            result.append(it.next());
            if (it.hasNext()) {
                result.append("/");
            }
        }

        // If result is empty, return "." to represent current directory
        if (result.length() == 0) {
            return ".";
        }
        return result.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to apply relative path", e);
    }
}

